  "implementation": "def solve(case):
    import itertools
    word_token_indices = case['word_token_indices']
    word_scores = case['word_scores']
    forced_words = case['forced_words']
    token_budget = case['token_budget']
    n = len(word_token_indices)
    forced_set = set(forced_words)
    forced_tokens = set()
    for idx in forced_words:
        forced_tokens.update(word_token_indices[idx])
    if len(forced_tokens) > token_budget:
        return []
    free_indices = [i for i in range(n) if i not in forced_set]
    best_score = -1
    best_selection = None
    for r in range(len(free_indices)+1):
        for combo in itertools.combinations(free_indices, r):
            selected = forced_words + list(combo)
            tokens = set(forced_tokens)
            for idx in combo:
                tokens.update(word_token_indices[idx])
            if len(tokens) <= token_budget:
                score = sum(word_scores[i] for i in selected)
                if score > best_score:
                    best_score = score
                    best_selection = selected
    return best_selection if best_selection is not None else []"
